// Logs → Skills tab — the skill-invocation history, AS GRAPH SOURCE (epic #3604).
//
// The rescue half of a P1 regression: the Skills page had three tabs, the move to Teams carried only
// the Library, and Runs has been unreachable since. This is where Runs belongs — it is HISTORY.
//
// IT IS NOT A VERBATIM PORT, AND THAT IS THE POINT. RunsTab rendered the skill LIBRARY joined to
// telemetry by name-slug. Measured against the real log: 82 lines, every one with an EMPTY skill name,
// so the aggregate yields zero buckets and the join yields zero rows. A verbatim port would render
// "No runs yet" forever — which is exactly what it did, unnoticed, while it was still reachable, and
// exactly the mistake the Flow tab was deleted for. The cause is filed as
// `skill-telemetry-has-never-recorded-a-skill-name`.
//
// So this tab is LOG-FIRST: it shows what the log HOLDS. The log does hold real history — when, which
// pane, and whether the invocation completed — and 79 recorded invocations must never render as
// "nothing happened". Three layers, in order of how much they can be trusted today:
//
//   1. the FEED      — always has content when the log does: when · pane · event · skill-or-unnamed
//   2. the ROLLUP    — the rescued Runs content; fills in the moment names arrive, no UI change
//   3. the NOTICE    — while names are missing, it says so WITH THE COUNT, so the gap is legible
//
// Preview note: the telemetry helpers are app-internal (unresolvable in this sandbox), so the row
// types and a sample log are inlined. Every prop still overrides the sample when composed.
import { StatTile } from "@/shared/ui/data/StatTile";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Banner } from "@/shared/ui/feedback/Banner";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

/** One parsed line of the skill usage log. `skill` is EMPTY when the payload carried no name. */
interface SkillRecord { ts: string; pane: string; event: string; skill: string }
/** One row of the per-skill rollup — the rescued Runs table. */
interface SkillRollupRow { slug: string; invocations: number; success: number; successRate: number; today: number; trend: number[] }

const SAMPLE_RECORDS: SkillRecord[] = [
  { ts: "2026-08-12T16:33:26Z", pane: "studio-code:mobile-crash-reporting", event: "PreToolUse", skill: "" },
  { ts: "2026-08-12T15:39:18Z", pane: "studio-code:mobile-studio-shell", event: "PostToolUse", skill: "" },
  { ts: "2026-08-12T15:07:56Z", pane: "studio-code:skills", event: "PreToolUse", skill: "" },
];

/** Rows whose invocation carried a name — the only ones the rollup can speak about. */
export function namedRecords(records: SkillRecord[]): SkillRecord[] {
  return records.filter((r) => r.skill !== "");
}

/** The rollup, ranked by invocations. Derived from the SAME stats the library page used, so the two
 *  can never disagree about how many times a skill ran. */
export function rollupRows(stats: Record<string, SkillRollupRow>): SkillRollupRow[] {
  return Object.values(stats).filter((s) => s.invocations > 0).sort((a, b) => b.invocations - a.invocations);
}

/** Distinct panes that invoked a skill — "who is using skills at all" is the question the log can
 *  answer today even with no names. */
export function panesInvoking(records: SkillRecord[]): number {
  return new Set(records.map((r) => r.pane)).size;
}

/** ISO → a short local time, for the feed. Invalid input renders as-is rather than "Invalid Date". */
export function fmtSkillTime(iso: string): string {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? iso : d.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

/** Success colour, matching the library's scale. */
function successColor(pct: number): string {
  return pct >= 90 ? "var(--success)" : pct >= 70 ? "var(--state-wait)" : "var(--danger)";
}

export interface SkillsTabProps {
  /** Parsed log records, NEWEST FIRST (the feed's order). */
  records?: SkillRecord[];
  /** Per-slug aggregates. Empty while no invocation carries a name. */
  stats?: Record<string, SkillRollupRow>;
  /** First poll has returned — distinguishes "still loading" from "genuinely empty". */
  loaded?: boolean;
  /** How many feed rows to render. */
  limit?: number;
}

export function SkillsTab({
  records = SAMPLE_RECORDS, stats = {}, loaded = true, limit = 60,
}: SkillsTabProps) {
  const named = namedRecords(records);
  const rollup = rollupRows(stats);
  const invocations = records.filter((r) => r.event === "PreToolUse").length;
  const completions = records.filter((r) => r.event === "PostToolUse").length;

  const COLS = "132px 1fr 104px 1fr";
  const RCOLS = "1.6fr 92px 62px 66px";

  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="invocations" v={invocations} sub="skill tool calls" />
        <StatTile k="completions" v={completions} tone="success" sub="reported a result" />
        <StatTile k="panes" v={panesInvoking(records)} sub="sessions using skills" />
        <StatTile k="named" v={named.length} tone={named.length === 0 && records.length > 0 ? "danger" : undefined} sub={records.length > 0 ? "of " + records.length + " records" : "nothing logged yet"} />
      </Box>

      {/* THE WHOLE REASON THIS TAB IS NOT A PORT. With rows in the log but no names on them, an empty
          rollup is not "no activity" — it is a broken emitter, and saying "No runs yet" here would be
          a false statement about the fleet rather than a true one about the data. */}
      {loaded && records.length > 0 && named.length === 0 && (
        <Banner tone="warn" style={{ marginBottom: 12 }}>
          <Text as="div" size={12}>
            <strong>{records.length} invocations recorded, none with a skill name.</strong> The per-skill
            rollup below stays empty until the hook records which skill ran — the invocations themselves
            are real and listed underneath. Tracked as <Text as="span" mono size={11}>skill-telemetry-has-never-recorded-a-skill-name</Text>.
          </Text>
        </Banner>
      )}

      {/* The rescued Runs content. Rendered only when it can say something true. */}
      {rollup.length > 0 && (
        <Box style={{ marginBottom: 16 }}>
          <Text as="div" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em", marginBottom: 7 }}>by skill · last 7 days</Text>
          <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
            <Box style={{ display: "grid", gridTemplateColumns: RCOLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
              <Box as="span">skill</Box>
              <Box as="span" style={{ textAlign: "right" }}>invocations</Box>
              <Box as="span" style={{ textAlign: "right" }}>today</Box>
              <Box as="span" style={{ textAlign: "right" }}>success</Box>
            </Box>
            {rollup.map((s, i) => (
              <Box key={s.slug} style={{ display: "grid", gridTemplateColumns: RCOLS, gap: 10, alignItems: "center", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
                <Text as="span" mono size={11} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.slug}</Text>
                <Text as="span" mono size={11} tone="muted" style={{ textAlign: "right" }}>{s.invocations}</Text>
                <Text as="span" mono size={11} tone="muted" style={{ textAlign: "right" }}>{s.today}</Text>
                <Text as="span" mono size={11} style={{ textAlign: "right", color: successColor(s.successRate) }}>{s.successRate}%</Text>
              </Box>
            ))}
          </Box>
        </Box>
      )}

      {records.length === 0 ? (
        // Genuinely empty, which is a DIFFERENT statement from the notice above.
        <EmptyState
          iconVariant="dashed" icon="◇" size="sm"
          title={loaded ? "No skill invocations logged" : "Reading the skill log…"}
          description="Each time an agent invokes a skill the hook appends a line here, with the pane it ran in and whether it completed."
        />
      ) : (
        <Box>
          <Text as="div" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em", marginBottom: 7 }}>recent invocations</Text>
          <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
            <Box style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
              <Box as="span">when</Box><Box as="span">pane</Box><Box as="span">event</Box><Box as="span">skill</Box>
            </Box>
            {records.slice(0, limit).map((r, i) => (
              <Box key={r.ts + ":" + r.pane + ":" + i} style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, alignItems: "baseline", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
                <Text as="span" mono size={10.5} tone="dim">{fmtSkillTime(r.ts)}</Text>
                <Text as="span" tone="muted" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.pane}</Text>
                <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                  <Box as="span" bg={r.event === "PostToolUse" ? "var(--success)" : "var(--accent)"} radius={99} style={{ width: 6, height: 6 }} />
                  <Text as="span" mono size={10.5}>{r.event === "PostToolUse" ? "completed" : "invoked"}</Text>
                </Box>
                {/* An unnamed row is the COMMON case right now, so it says what it is rather than
                    rendering a blank cell that reads as a missing value in the table. */}
                {r.skill !== "" ? (
                  <Text as="span" mono size={11}>{r.skill}</Text>
                ) : (
                  <Text as="span" tone="dim" style={{ fontStyle: "italic" }}>name not recorded</Text>
                )}
              </Box>
            ))}
          </Box>
          {records.length > limit && (
            <Text as="div" mono size={10} tone="dim" style={{ marginTop: 7 }}>
              showing {limit} of {records.length}
            </Text>
          )}
        </Box>
      )}
    </Box>
  );
}

