// The Logs → Skills tab — the skill-invocation history.
//
// Carried ON the record, so it runs against the copy that actually mounts.
//
// The assertions that matter most are about what the tab says when the DATA is broken: the whole
// reason this is not a verbatim port of RunsTab is that RunsTab said "No runs yet" while 79
// invocations sat in the log.
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { SkillsTab, namedRecords, rollupRows, panesInvoking, fmtSkillTime } from "./SkillsTab";

/** Shaped like the REAL log: names empty, which is the state that motivated this tab. */
const UNNAMED = [
  { ts: "2026-08-12T16:33:26Z", pane: "studio-code:crash", event: "PreToolUse", skill: "" },
  { ts: "2026-08-12T15:39:18Z", pane: "studio-code:shell", event: "PostToolUse", skill: "" },
  { ts: "2026-08-12T15:07:56Z", pane: "studio-code:crash", event: "PreToolUse", skill: "" },
];

const NAMED = [
  { ts: "2026-08-12T16:33:26Z", pane: "a:b", event: "PreToolUse", skill: "open-a-clean-pr" },
  { ts: "2026-08-12T16:34:00Z", pane: "a:b", event: "PostToolUse", skill: "open-a-clean-pr" },
];

const STATS = {
  "open-a-clean-pr": { slug: "open-a-clean-pr", invocations: 9, success: 8, successRate: 89, today: 2, trend: [0, 1, 2, 0, 3, 1, 2] },
  "compliance-docs": { slug: "compliance-docs", invocations: 3, success: 3, successRate: 100, today: 0, trend: [1, 0, 0, 1, 0, 0, 1] },
  "never-run": { slug: "never-run", invocations: 0, success: 0, successRate: 0, today: 0, trend: [0, 0, 0, 0, 0, 0, 0] },
};

describe("pure helpers", () => {
  it("namedRecords keeps only invocations that carried a name", () => {
    expect(namedRecords(UNNAMED)).toHaveLength(0);
    expect(namedRecords([...UNNAMED, ...NAMED])).toHaveLength(2);
  });

  it("rollupRows ranks by invocations and drops the never-run", () => {
    // A library skill with zero invocations is not history; it belongs on the library page, not here.
    expect(rollupRows(STATS).map((r) => r.slug)).toEqual(["open-a-clean-pr", "compliance-docs"]);
  });

  it("panesInvoking counts DISTINCT panes, not rows", () => {
    expect(panesInvoking(UNNAMED)).toBe(2); // three rows, two panes
    expect(panesInvoking([])).toBe(0);
  });

  it("fmtSkillTime renders bad input verbatim rather than 'Invalid Date'", () => {
    // 3 of the real log's 82 lines have an EMPTY timestamp. The parser drops those, but this is the
    // display side and it must not turn a data problem into a nonsense string on screen.
    expect(fmtSkillTime("not-a-date")).toBe("not-a-date");
    expect(fmtSkillTime("")).toBe("");
    expect(fmtSkillTime("2026-08-12T16:33:26Z")).not.toContain("Invalid");
  });
});

describe("SkillsTab — records present but UNNAMED (the real log's state)", () => {
  it("says how many invocations were recorded instead of implying none happened", () => {
    // THE POINT OF THE WHOLE TAB. RunsTab rendered "No runs yet" against exactly this data.
    render(<SkillsTab records={UNNAMED} stats={{}} loaded />);
    expect(screen.getByText(/3 invocations recorded, none with a skill name/)).toBeInTheDocument();
    expect(screen.queryByText(/No skill invocations logged/)).toBeNull();
  });

  it("still lists every invocation, with the missing name stated rather than blank", () => {
    render(<SkillsTab records={UNNAMED} stats={{}} loaded />);
    expect(screen.getAllByText("name not recorded")).toHaveLength(3);
    expect(screen.getAllByText("studio-code:crash")).toHaveLength(2);
  });

  it("distinguishes an invocation from a completion", () => {
    render(<SkillsTab records={UNNAMED} stats={{}} loaded />);
    expect(screen.getAllByText("invoked")).toHaveLength(2);
    expect(screen.getAllByText("completed")).toHaveLength(1);
  });

  it("names the tracking ref, so the gap is followable from the screen", () => {
    render(<SkillsTab records={UNNAMED} stats={{}} loaded />);
    expect(screen.getByText("skill-telemetry-has-never-recorded-a-skill-name")).toBeInTheDocument();
  });
});

describe("SkillsTab — the rescued Runs rollup", () => {
  it("renders per-skill invocations, today and success once names exist", () => {
    render(<SkillsTab records={NAMED} stats={STATS} loaded />);
    // The name appears in BOTH the rollup and the feed below it, which is correct — so assert on
    // the rollup's own numbers rather than a name that legitimately occurs twice.
    expect(screen.getAllByText("open-a-clean-pr").length).toBeGreaterThan(0);
    expect(screen.getByText("89%")).toBeInTheDocument();
    expect(screen.getByText("100%")).toBeInTheDocument();
  });

  it("drops the unnamed-warning once ANY invocation carries a name", () => {
    render(<SkillsTab records={NAMED} stats={STATS} loaded />);
    expect(screen.queryByText(/none with a skill name/)).toBeNull();
  });

  it("hides the rollup entirely when it has nothing true to say", () => {
    // An empty table with a header reads as "zero runs"; absent, it makes no claim at all.
    render(<SkillsTab records={UNNAMED} stats={{}} loaded />);
    expect(screen.queryByText("by skill · last 7 days")).toBeNull();
  });
});

describe("SkillsTab — the genuinely empty cases", () => {
  it("an empty log is an empty STATE, distinct from the unnamed notice", () => {
    render(<SkillsTab records={[]} stats={{}} loaded />);
    expect(screen.getByText("No skill invocations logged")).toBeInTheDocument();
    expect(screen.queryByText(/none with a skill name/)).toBeNull();
  });

  it("before the first poll returns it says it is reading, not that there is nothing", () => {
    // "Nothing logged" is a claim about the fleet; making it before reading the log is a guess.
    render(<SkillsTab records={[]} stats={{}} loaded={false} />);
    expect(screen.getByText("Reading the skill log…")).toBeInTheDocument();
  });
});

describe("SkillsTab — the feed is bounded", () => {
  it("caps the rows and says how many it is showing", () => {
    const many = Array.from({ length: 90 }, (_, i) => ({
      ts: "2026-08-12T16:33:26Z", pane: "p" + i, event: "PreToolUse", skill: "",
    }));
    render(<SkillsTab records={many} stats={{}} loaded limit={20} />);
    expect(screen.getByText("showing 20 of 90")).toBeInTheDocument();
    // Silent truncation would read as "that is all there was".
    expect(screen.getAllByText("name not recorded")).toHaveLength(20);
  });
});
